const crypto = require('crypto');
const item = $input.first().json;
const h = item.headers || {};
const body = JSON.stringify(item.body);
const ts = h['x-grc-timestamp'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', $env.GRC_FLOW_WEBHOOK_SECRET)
  .update(ts + '.' + body).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
if (!fresh || h['x-grc-signature'] !== expected) {
  throw new Error('GRC-Flow signature check failed');
}
const e = item.body;
// Only failures and checker alerts page a person; run.completed is logged by n8n's history.
if (e.type === 'run.failed') {
  return [{ json: { text: `:x: GRC-Flow run ${e.data.run_id} failed for ${e.data.org_id}: ${e.data.error}` } }];
}
if (e.type === 'checker.alert') {
  const what = e.data.kind === 'health' ? `failing: ${e.data.failing.join(', ')}` : 'canary results differ';
  return [{ json: { text: `:rotating_light: GRC-Flow checker (${e.data.kind}) ${what}` } }];
}
if (e.type === 'run.completed' && e.data.findings.some(f => f.status === 'gap')) {
  const gaps = e.data.findings.filter(f => f.status === 'gap').map(f => f.check).join(', ');
  return [{ json: { text: `:warning: New DPDPA gaps for ${e.data.org_id}: ${gaps} (run ${e.data.run_id})` } }];
}
return [];
